package vn.svframe.svframelib.api.crafting.recipes;
import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.util.Ref; import java.util.*;
public abstract class SVFrameRecipe { private final String name; protected final ArrayList<SVFrameRecipeIngredient> ingredients; private boolean live; public SVFrameRecipe(String name,ArrayList<SVFrameRecipeIngredient> ingredients){this.name=Objects.requireNonNull(name);this.ingredients=new ArrayList<>(ingredients);} public SVFrameRecipe(String name,SVFrameRecipeIngredient... ingredients){this(name,new ArrayList<>(Arrays.asList(ingredients)));} public abstract void addIngredient(SVFrameRecipeIngredient ingredient); public ArrayList<SVFrameRecipeIngredient> getIngredients(){return new ArrayList<>(ingredients);} public void clearIngredients(){ingredients.clear();} public String getName(){return name;} public abstract SVFrameRecipeStation getType(); public abstract SVFrameRecipeInventory matches(SVFrameRecipeInventory inventory,Ref<Integer> amount); public void load(){live=true;} public void unload(){live=false;} public boolean isLive(){return live;} }
